738373f586b57", "sequence": 113}, {"request_id": "dialogue-114", "events": [{"role": "user", "content": "Joanna: Appreciated! I think just having someone to support me throughout the whole process is such a blessing. It gives me the motivation to keep pushing forward.", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_98dcedd34d3440a2ab70893a86da78e9", "session_id": "session_b03e3d958201431cb10738373f586b57", "sequence": 114}, {"request_id": "dialogue-115", "events": [{"role": "user", "content": "Nate: Glad to hear my support makes a difference, Joanna. I'm here for you!", "speaker": "Nate", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_9ce021f26c914f1a873a76c7ede639d2", "session_id": "session_b03e3d958201431cb10738373f586b57", "sequence": 115}, {"request_id": "dialogue-116", "events": [{"role": "user", "content": "Joanna: [Image: a photo of a cinema ticket on a chair] Always good to hear! See you later!", "speaker": "Joanna", "occurred_at": "2022-03-18T18:59:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_258cff125f444fafa778493fe39b13bf", "session_id": "session_b03e3d958201431cb10738373f586b57", "sequence": 116}]
